head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[datePicker > P > monthNames]<br/>월 컬럼에 표시할 라벨을 콤마(',')로 구분하여 설정합니다.",
    "validation" : [
        "월 컬럼에 표시할 라벨을 콤마(',')로 구분하여 설정합니다.",
        "String 값으로 1월부터 12월까지 12개의 라벨을 콤마(',')로 구분하여 설정합니다.",
        "값을 설정하지 않으면 언어팩(DatePicker_monthNames)에서 가져온 값이 적용되며 기본값은 '1월,2월,3월...' 입니다.",
        "12 개 미만으로 설정하면 부족한 월의 라벨이 정상적으로 표시되지 않습니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let monthNamesValue = par_monthNames.getText();

    let properties = {};

    // '미설정' 선택 시 properties 에 추가하지 않아 엔진 기본값 (언어팩 한국어 '1월,2월,...') 적용 확인
    if (monthNamesValue !== "" && monthNamesValue !== "미설정") {
        properties.monthNames = monthNamesValue;
    }

    let cList = $c.gcm.createCList(properties);

    await $c.gcm.createBasicDatePicker(cList);
}



// 월 컬럼 itemArr 라벨 출력
scwin.getMonthNamesInfo = function () {
    // 월 컬럼 존재 여부 확인 (calendarValueType 기본값 'yearMonthDate' 에 month 컬럼 포함)
    if (!target1.colTypeObj || !target1.colTypeObj.hasOwnProperty('month')) {
        wf_body_bottom.getObj("scwin").setReturnValue("[월 컬럼 적용] 월 컬럼이 존재하지 않아 monthNames 가 적용되지 않음");
        return;
    }

    let monthIdx = target1.colTypeObj['month'];
    let monthCol = target1.childControlList[monthIdx];

    if (!monthCol || !monthCol.itemArr || monthCol.itemArr.length === 0) {
        wf_body_bottom.getObj("scwin").setReturnValue("[월 컬럼 라벨] 컬럼 정보 없음");
        return;
    }

    // 전체 12개 라벨 출력 (12개 미만 설정 시 부족한 월 라벨 비정상 표시 확인)
    let allLabels = [];
    for (let i = 0; i < monthCol.itemArr.length; i++) {
        allLabels.push(monthCol.itemArr[i].label);
    }
    wf_body_bottom.getObj("scwin").setReturnValue("[월 컬럼 전체 라벨] [" + allLabels.join(', ') + "]");
}



scwin.btn_getInfo_onclick = function (e) {
    scwin.getMonthNamesInfo();
}
